<script setup lang="ts">
import {usePageActivity} from '../page-activity';
const listLoaded=ref(false);
const pageActive=usePageActivity();
import Modal from '../components/Modal.vue';
import EmptyState from '../components/EmptyState.vue';
import Pagination from '../components/Pagination.vue';
import {confirmOperation} from '../modal';

import {useLatestRead,useOperationRead,collectPages} from '../data-sync';
import { useScopedRefresh } from '../scoped-refresh';
import { isHR } from '../policy';
import { useFeedback } from '../feedback';
import { markDirty } from '../workspace';
import { formatBeijing,stateLabel,eventLabel } from '../presentation';
import { ref, computed } from 'vue';
import { ApiError,me, listDepartments, type Department } from '../api';
import { all, courseApi, downloadEmployees, importEmployees, saveFile, errorText, tag, type Employee, type Position, type Page, type ImportResult } from '../course-api';
const pageSize=ref(20),canExport=ref(false),importOpen=ref(false);
const tabPath='/employees';
const items=ref<Employee[]>([]), positions=ref<Position[]>([]), departments=ref<Department[]>([]), canWrite=ref(false), q=ref(''), depFilter=ref(''), statusFilter=ref('');
const page=ref(1), total=ref(0), busy=ref(false), loading=ref(false), error=ref(''), notice=ref(''), selected=ref<Employee|null>(null);
const mode=ref<'create'|'edit'|'detail'|'transfer'|null>(null);
const blank=()=>({employee_no:'',full_name:'',current_department_id:'',current_position_id:'',hire_date:new Date().toISOString().slice(0,10),employment_status:'ACTIVE'});
const form=ref(blank()), transfer=ref({department_id:'',position_id:''});
const file=ref<File|null>(null), format=ref<'csv'|'xlsx'>('csv'), preflight=ref<ImportResult|null>(null);
const departmentName=(id:string)=>departments.value.find(d=>d.id===id)?.name||'名称未加载';
const positionName=(id:string)=>positions.value.find(p=>p.id===id)?.name||'名称未加载';
const available=computed(()=>positions.value.filter(p=>p.status==='ACTIVE'&&p.department_id===form.value.current_department_id));
const listRead=useLatestRead(),optionsRead=useLatestRead(),operate=useOperationRead(busy,error);
const selectionWarning=computed(()=>{if(!mode.value||mode.value==='detail')return '';const d=mode.value==='transfer'?transfer.value.department_id:form.value.current_department_id,p=mode.value==='transfer'?transfer.value.position_id:form.value.current_position_id;
 if(d&&!departments.value.some(row=>row.id===d&&row.status==='ACTIVE'))return '原选择的部门已停用或不可用，请重新选择。';
 if(p&&!positions.value.some(row=>row.id===p&&row.status==='ACTIVE'&&row.department_id===d))return '原选择的职位已停用、变更部门或不可用，请重新选择。';return '';});
async function load(strict=false){const query=new URLSearchParams({q:q.value,page:String(page.value),page_size:String(pageSize.value),...(depFilter.value?{department_id:depFilter.value}:{}),...(statusFilter.value?{status:statusFilter.value}:{})});try{await listRead.run(query.toString(),()=>courseApi<Page<Employee>>(`/employees?${query}`),{start:()=>{loading.value=true;error.value='';},success:data=>{items.value=data.items;total.value=data.total;listLoaded.value=true;},failure:e=>{error.value=errorText(e);},finish:()=>{loading.value=false;}});}catch(e){if(strict===true)throw e;}}
async function options(){await optionsRead.run('options',async()=>{const [profile,ps,ds]=await Promise.all([me(),all<Position>('/positions'),collectPages(page=>listDepartments('',page,100))]);return {profile,ps,ds};},{success:({profile,ps,ds})=>{canWrite.value=isHR(profile);canExport.value=canWrite.value||(profile.roles.includes('MANAGER')&&!!profile.employee_id&&profile.employment_valid!==false);positions.value=ps;departments.value=ds;}});}
async function open(item:Employee|null,action:typeof mode.value){if(busy.value)return;await operate('open:'+String(item?.id||'new')+':'+action,async()=>{await options();return item?await courseApi<Employee>(`/employees/${encodeURIComponent(item.id)}`):null;},latest=>{selected.value=latest;mode.value=action;form.value=latest?{employee_no:latest.employee_no,full_name:latest.full_name,current_department_id:latest.current_department_id,current_position_id:latest.current_position_id,hire_date:latest.hire_date,employment_status:latest.employment_status}:blank();transfer.value={department_id:'',position_id:''};});}
async function openImport(){if(busy.value)return;await operate('import',async()=>{if(!isHR(await me()))throw new Error('当前账号没有导入员工的权限');},()=>{importOpen.value=true;file.value=null;preflight.value=null;});}
async function save(){if(busy.value)return;if(selectionWarning.value){error.value=selectionWarning.value;return;}busy.value=true;error.value='';notice.value='';try{
  if(mode.value==='transfer'&&selected.value)await courseApi(`/employees/${encodeURIComponent(selected.value.id)}/transfer`,'POST',transfer.value,tag(selected.value));
  else if(selected.value)await courseApi(`/employees/${encodeURIComponent(selected.value.id)}`,'PATCH',form.value,tag(selected.value));
  else await courseApi('/employees','POST',form.value);
  markDirty(tabPath,false);notice.value='员工档案已保存';mode.value=null;await load();
}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function archive(item:Employee){await confirmOperation({title:'离职归档',message:`确认将“${item.employee_no} · ${item.full_name}”离职归档？历史将保留，关联账号将退出登录。`,danger:true},async()=>{busy.value=true;error.value='';notice.value='';try{const latest=await courseApi<Employee>(`/employees/${encodeURIComponent(item.id)}`);await courseApi(`/employees/${encodeURIComponent(item.id)}/archive`,'POST',{},tag(latest));notice.value='已离职归档';await load();}finally{busy.value=false;}});}
function pick(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null;preflight.value=null;error.value='';notice.value='';if(file.value)format.value=file.value.name.toLowerCase().endsWith('.xlsx')?'xlsx':'csv';}
async function upload(commit=false){if(busy.value)return;if(!file.value)return;busy.value=true;error.value='';notice.value='';try{preflight.value=await importEmployees(file.value,format.value,commit?'commit':'preflight');if(preflight.value.valid&&commit){notice.value=`已导入 ${preflight.value.imported} 名员工`;markDirty(tabPath,false,'file');file.value=null;importOpen.value=false;await load();}}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function download(kind:'csv'|'xlsx',template=false){if(busy.value)return;busy.value=true;error.value='';try{await saveFile(await downloadEmployees(kind,template,q.value,depFilter.value,statusFilter.value),`employees${template?'-template':''}.${kind}`);}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
const {scopeLocked,scopeFailure,retryScope,scopeStyle}=useScopedRefresh(async current=>{
 await Promise.all([options(),load(true)]);if(!current())return;const target=selected.value;
 if(target){try{const fresh=await courseApi<Employee>(`/employees/${encodeURIComponent(target.id)}`);if(current()&&selected.value?.id===target.id&&mode.value==='detail')selected.value=fresh;}
 catch(e){if(!current()||selected.value?.id!==target.id)return;if(e instanceof ApiError&&[403,404].includes(e.status)){selected.value=null;mode.value=null;form.value=blank();markDirty(tabPath,false);}else throw e;}}
},['employees','positions','departments']);
useFeedback(notice,error,tabPath);
</script>
<template><div :style="scopeStyle" class="business-page"><p v-if="scopeLocked" class="verification" role="status">{{scopeFailure||'加载中…'}}<button v-if="scopeFailure" @click="retryScope">重试</button></p><main v-show="!scopeLocked">
  <div class="section-heading"><h1>员工管理</h1><button v-if="canWrite" :disabled="busy" @click="open(null,'create')">新增员工</button></div><p v-if="busy&&!mode&&!importOpen" role="status">正在读取操作所需数据…</p><p v-if="error" class="error feedback" role="alert">{{error}}</p><p v-if="notice" class="success feedback" role="status">{{notice}}</p>
  <section class="card"><form class="search-row" @submit.prevent="page=1;load()"><label>工号 / 姓名<input v-model="q" maxlength="128"></label><label>部门<select aria-label="部门" v-model="depFilter"><option value="">全部授权部门</option><option v-for="d in departments" :value="d.id" :key="d.id">{{d.name}}</option></select></label><label>状态<select aria-label="状态" v-model="statusFilter"><option value="">全部</option><option value="PRE_HIRE">{{stateLabel('PRE_HIRE')}}</option><option value="PROBATION">{{stateLabel('PROBATION')}}</option><option value="ACTIVE">{{stateLabel('ACTIVE')}}</option><option value="EXIT_PROCESSING">{{stateLabel('EXIT_PROCESSING')}}</option><option value="TERMINATED">{{stateLabel('TERMINATED')}}</option></select></label><button :disabled="loading">查询</button></form>
  <p v-if="!scopeLocked&&(loading||!listLoaded&&!error)" role="status">加载中…</p><EmptyState v-else-if="listLoaded&&!error&&!items.length" text="暂无员工数据"/><div v-else-if="listLoaded&&!error" class="table-scroll"><table><thead><tr><th>工号 / 姓名</th><th>部门 / 职位</th><th>入职日</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td>{{row.employee_no}}<br>{{row.full_name}}</td><td>{{departmentName(row.current_department_id)}}<br>{{positionName(row.current_position_id)}}</td><td>{{row.hire_date}}</td><td>{{stateLabel(row.employment_status)}}</td><td><button class="text-button" :disabled="busy" @click="open(row,'detail')">详情 / 历史</button><template v-if="canWrite&&row.employment_status!=='TERMINATED'"><button class="text-button" :disabled="busy" @click="open(row,'edit')">编辑</button><button class="text-button" :disabled="busy" @click="open(row,'transfer')">调动</button><button class="text-button" :disabled="busy||!!mode" @click="archive(row)">离职归档</button></template></td></tr></tbody></table></div>
  <Pagination :page="page" :page-size="pageSize" :total="total" :busy="loading" @page="page=$event;load()" @size="pageSize=$event;page=1;load()"/></section>
  <Modal :return-focus="operate.opener.value" v-if="mode" :title="mode==='detail'?'员工详情':mode==='transfer'?'组织调动':mode==='edit'?'编辑员工':'新增员工'" :busy="busy" :error="error" :track-changes="mode!=='detail'" :concealed="scopeLocked" wide @retry="retryScope" @close="mode=null;selected=null">
    <template v-if="mode==='detail'&&selected"><dl><dt>工号 / 姓名</dt><dd>{{selected.employee_no}} · {{selected.full_name}}</dd><dt>部门</dt><dd>{{departmentName(selected.current_department_id)}}</dd><dt>职位</dt><dd>{{positionName(selected.current_position_id)}}</dd><dt>入职日期 / 状态</dt><dd>{{selected.hire_date}} · {{stateLabel(selected.employment_status)}}</dd></dl><h3>变更历史</h3><ul><li v-for="(event,index) in selected.history" :key="index">{{formatBeijing(event.created_at)}} · {{eventLabel(event.event_type)}}<span v-if="event.new_status"> · {{event.old_status?stateLabel(event.old_status):'无'}} → {{stateLabel(event.new_status)}}</span></li></ul><p v-if="!selected.history?.length" class="muted">没有历史事件。</p></template>
    <form v-else @submit.prevent="save"><fieldset :disabled="busy"><p v-if="selectionWarning" class="error" role="alert">{{selectionWarning}}</p><template v-if="mode==='transfer'"><label>新部门<select aria-label="新部门" v-model="transfer.department_id" required @change="transfer.position_id=''"><option disabled value="">请选择</option><option v-if="transfer.department_id&&!departments.some(d=>d.id===transfer.department_id&&d.status==='ACTIVE')" disabled :value="transfer.department_id">原选择的部门不可用，请核对</option><option v-for="d in departments.filter(x=>x.status==='ACTIVE')" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>新职位<select aria-label="新职位" v-model="transfer.position_id" required><option disabled value="">请选择</option><option v-if="transfer.position_id&&!positions.some(p=>p.id===transfer.position_id&&p.status==='ACTIVE'&&p.department_id===transfer.department_id)" disabled :value="transfer.position_id">原选择的职位不可用，请核对</option><option v-for="p in positions.filter(x=>x.status==='ACTIVE'&&x.department_id===transfer.department_id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label></template>
    <div v-else class="form-columns"><label>工号<input v-model="form.employee_no" required maxlength="64"></label><label>姓名<input v-model="form.full_name" required maxlength="128"></label><label>部门<select aria-label="部门" v-model="form.current_department_id" :disabled="mode==='edit'" required @change="form.current_position_id=''"><option disabled value="">请选择</option><option v-if="form.current_department_id&&!departments.some(d=>d.id===form.current_department_id&&d.status==='ACTIVE')" disabled :value="form.current_department_id">原选择的部门不可用，请核对</option><option v-for="d in departments.filter(x=>x.status==='ACTIVE')" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>职位<select aria-label="职位" v-model="form.current_position_id" :disabled="mode==='edit'" required><option disabled value="">请选择</option><option v-if="form.current_position_id&&!positions.some(p=>p.id===form.current_position_id&&p.status==='ACTIVE'&&p.department_id===form.current_department_id)" disabled :value="form.current_position_id">原选择的职位不可用，请核对</option><option v-for="p in available" :key="p.id" :value="p.id">{{p.name}} · {{p.grade_code}}</option></select></label><label>入职日期<input v-model="form.hire_date" type="date" required :disabled="mode==='edit'"></label><label>状态<select aria-label="状态" v-model="form.employment_status"><option value="PRE_HIRE">{{stateLabel('PRE_HIRE')}}</option><option value="PROBATION">{{stateLabel('PROBATION')}}</option><option value="ACTIVE">{{stateLabel('ACTIVE')}}</option><option value="EXIT_PROCESSING">{{stateLabel('EXIT_PROCESSING')}}</option></select></label></div><p class="muted">变更部门或职位请使用“调动”，历史记录将保留。</p><div class="form-actions"><button type="button" class="secondary" data-modal-cancel>取消</button><button>保存员工</button></div></fieldset></form>
  </Modal>
  <section v-if="canExport" class="card employee-data"><h2>员工数据导入与导出</h2>
  <div class="employee-export"><h3>导出员工资料</h3><p class="muted">导出当前查询结果中的员工资料。</p><div class="form-actions"><button type="button" v-for="kind in (['csv','xlsx'] as const)" :key="kind" :disabled="busy" @click="download(kind)">导出 {{kind.toUpperCase()}}（当前查询）</button></div></div>
  <div v-if="canWrite" class="employee-import"><h3>批量导入员工</h3><p class="muted">请先下载模板，填写员工信息后再导入。</p><div class="template-downloads"><button type="button" v-for="kind in (['csv','xlsx'] as const)" :key="kind" class="secondary" :disabled="busy" @click="download(kind,true)">下载 {{kind.toUpperCase()}} 模板</button></div><div class="employee-import-entry"><button type="button" :disabled="busy" @click="openImport">导入员工</button></div></div>
</section>
<Modal :return-focus="operate.opener.value" v-if="importOpen&&canWrite" title="导入员工" scope="file" :busy="busy" :error="error" :concealed="scopeLocked" wide @retry="retryScope" @close="importOpen=false;file=null;preflight=null"><p class="muted">选择填好的 CSV 或 XLSX 模板后预检。请先修正全部错误，再确认导入；有错误时不会导入任何员工。</p><label>选择模板文件<input type="file" accept=".csv,.xlsx" @change="pick"></label><button :disabled="!file||busy" @click="upload()">预检文件</button><button class="secondary" :disabled="!file||busy||!preflight?.valid" @click="upload(true)">导入</button>
    <p v-if="preflight?.valid" class="success" role="status">预检通过{{preflight.count!==undefined?'，共 '+preflight.count+' 条员工资料':''}}，请确认后导入。</p><template v-if="preflight&&!preflight.valid"><p class="error">尚未导入，请按以下行号和原因修正后重新预检。</p><ul class="error" role="alert"><li v-for="(issue,index) in preflight.errors" :key="`${issue.row}-${issue.code}-${index}`">第 {{issue.row}} 行{{issue.field ? ` · ${issue.field}` : ''}}：{{issue.message || '字段或引用不合法，请核对模板'}}</li></ul></template><div class="form-actions"><button type="button" class="secondary" data-modal-cancel>关闭</button></div></Modal></main></div></template>
